import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import MyContext from '../contexts/MyContext';

class Menu extends Component {
  static contextType = MyContext;

  render() {
    return (
      <nav style={styles.navBar}>
        <div style={styles.brand}>Nhà hàng Văn Lang</div>
        <div style={styles.menuList}>
          <Link to="/admin/report" style={styles.navItem}>Báo cáo</Link>
          <Link to="/admin/category" style={styles.navItem}>Danh mục</Link>
          <Link to="/admin/product" style={styles.navItem}>Thực đơn</Link>
          <Link to="/admin/order" style={styles.navItem}>Đơn hàng</Link>
          <Link to="/admin/customer" style={styles.navItem}>Khách hàng</Link>
          <Link to="/admin/voucher" style={styles.navItem}>Mã giảm giá</Link>
        </div>
        <div style={styles.userSection}>
          <span>Hi Quản lý</span>
          <button 
            onClick={() => { this.context.setToken(''); this.context.setUsername(''); }}
            style={styles.btnLogout}
          >
            Logout
          </button>
        </div>
      </nav>
    );
  }
}

const styles = {
  navBar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    backgroundColor: '#4A2E2B',
    padding: '12px 24px',
    color: '#FFF',
    borderRadius: '0 0 12px 12px'
  },
  brand: { fontWeight: 'bold', fontSize: '18px' },
  menuList: { display: 'flex', gap: '20px' },
  navItem: { color: '#FFF', textDecoration: 'none', fontSize: '15px' },
  userSection: { display: 'flex', alignItems: 'center', gap: '12px' },
  btnLogout: {
    backgroundColor: '#C85A32',
    color: '#FFF',
    border: 'none',
    padding: '6px 16px',
    borderRadius: '20px',
    cursor: 'pointer'
  }
};

export default Menu;
